import {CLASS_LIST,CLASSES,classAppearance} from './classes.js';
import {prepareCharacterPortraits,portraitFor} from './character-portraits.js';

export function createRosterPicker({getState,onChoose,onClose}){
 const dialog=document.createElement('dialog');dialog.className='roster-dialog';dialog.setAttribute('aria-labelledby','roster-title');
 dialog.innerHTML=`<header class="roster-header"><span class="eyebrow">HALLOWMERE · THE ASHEN VIGIL</span><h2 id="roster-title">Choose your oath</h2><div class="roster-ornament" aria-hidden="true"></div><button class="roster-close" aria-label="Close character selection">×</button></header>
 <div class="roster-layout"><div class="roster-wheel"><div class="roster-ring" aria-hidden="true"></div><div class="roster-portrait"><img alt="" draggable="false"><span class="roster-appearance-name"></span></div><nav class="roster-classes" aria-label="Playable classes"></nav><button class="roster-step roster-previous" aria-label="Previous character"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6M8 12h12"/></svg></button><button class="roster-step roster-next" aria-label="Next character"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6M16 12H4"/></svg></button><span class="roster-position" aria-hidden="true"></span></div>
 <section class="roster-description" aria-labelledby="roster-name"><p class="eyebrow roster-role"></p><h3 id="roster-name" class="roster-name" aria-live="polite" aria-atomic="true"></h3><p class="roster-story"></p><div class="roster-stats"></div><div class="roster-skills"></div><details class="roster-loadout"><summary>Equipment</summary><dl class="roster-equipment"></dl></details><button class="primary-button roster-confirm">Enter the vigil</button><p class="roster-note" role="status">Change class at any sanctuary. Your equipment and progress travel with you.</p></section></div>`;
 document.body.append(dialog);
 const q=selector=>dialog.querySelector(selector);let chosen='sorcerer',pending=false,prepared=false;
 try{const saved=JSON.parse(localStorage.getItem('hallowmere.character-choice')||'null');if(saved&&Object.hasOwn(CLASSES,saved.classId)){chosen=saved.classId;}}catch{}
 q('.roster-classes').innerHTML=CLASS_LIST.map((c,i)=>{const angle=-Math.PI/2+i*Math.PI*2/CLASS_LIST.length;return `<button data-class-choice="${c.id}" aria-label="Select ${c.name}" aria-pressed="false" style="--x:${50+Math.cos(angle)*40}%;--y:${50+Math.sin(angle)*40}%"><span class="roster-medallion"><img alt="" hidden draggable="false"></span><span class="roster-class-label">${c.name}</span></button>`;}).join('');
 function render(){
  const c=CLASSES[chosen],look=classAppearance(chosen,c.concept),image=portraitFor(chosen,c.concept);
  q('.roster-role').textContent=c.role;q('.roster-role').style.color=look?.color||c.color;q('.roster-name').textContent=c.name;q('.roster-story').textContent=c.description;
  q('.roster-stats').innerHTML=`<span><strong>${c.hp}</strong> Vitality</span><span><strong>${c.mana}</strong> Essence</span><span><strong>${c.speed.toFixed(1)}</strong> Speed</span>`;
  q('.roster-equipment').innerHTML=`<div><dt>Weapon</dt><dd>${look?.weapon||c.weapon}</dd></div><div><dt>Off hand</dt><dd>${look?.focus||c.focus}</dd></div>`;
  q('.roster-skills').innerHTML=['attack','bolt','dodge','nova'].map((key,i)=>{const s=c.abilities[key];return `<details><summary><kbd>${['LMB','RMB','1','2'][i]}</kbd><strong>${s.name}</strong></summary><p>${s.description}</p></details>`;}).join('');
  q('.roster-portrait img').hidden=!image;if(image)q('.roster-portrait img').src=image;q('.roster-portrait img').alt=`${look?.name||c.name} with ${look?.weapon||c.weapon}`;q('.roster-appearance-name').textContent=image?look?.name||c.name:'Preparing characters…';
  dialog.querySelectorAll('[data-class-choice]').forEach(b=>{const selected=b.dataset.classChoice===chosen,hero=CLASSES[b.dataset.classChoice],portrait=portraitFor(hero.id,hero.concept),img=b.querySelector('img');b.setAttribute('aria-pressed',String(selected));b.tabIndex=selected?0:-1;b.disabled=pending;img.hidden=!portrait;if(portrait)img.src=portrait;});
  q('.roster-previous').disabled=pending;q('.roster-next').disabled=pending;
  q('.roster-position').textContent=`${String(CLASS_LIST.findIndex(hero=>hero.id===chosen)+1).padStart(2,'0')} / ${String(CLASS_LIST.length).padStart(2,'0')}`;
  q('.roster-confirm').disabled=pending||!prepared;q('.roster-confirm').textContent=pending?'Joining the vigil…':getState().classId?'Continue as '+c.name:'Enter the vigil';q('.roster-close').hidden=!getState().classId;
 }
 function close(){if(pending||!getState().classId)return;dialog.close();}
 function step(direction){if(pending)return;const index=CLASS_LIST.findIndex(c=>c.id===chosen);chosen=CLASS_LIST[(index+direction+CLASS_LIST.length)%CLASS_LIST.length].id;render();}
 q('.roster-previous').onclick=()=>step(-1);q('.roster-next').onclick=()=>step(1);
 q('.roster-wheel').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;event.preventDefault();if(pending)return;const focusPortrait=event.target.closest('[data-class-choice]');if(event.key==='Home'||event.key==='End'){chosen=CLASS_LIST[event.key==='Home'?0:CLASS_LIST.length-1].id;render();}else step(['ArrowLeft','ArrowUp'].includes(event.key)?-1:1);if(focusPortrait)q('[data-class-choice="'+chosen+'"]').focus({preventScroll:true});});
 dialog.addEventListener('click',event=>{const classButton=event.target.closest('[data-class-choice]');if(classButton&&!pending){chosen=classButton.dataset.classChoice;render();}});
 q('.roster-close').onclick=close;dialog.addEventListener('cancel',e=>{if(!getState().classId||pending)e.preventDefault();});dialog.addEventListener('close',onClose);
 q('.roster-confirm').onclick=()=>{const choice={classId:chosen,appearanceId:CLASSES[chosen].concept};if(onChoose(choice)){pending=true;q('.roster-note').textContent='Preparing your character…';render();}else q('.roster-note').textContent='Waiting for a connection. Try again when the vigil reconnects.';};
 return {get open(){return dialog.open;},async show(){const state=getState();if(CLASSES[state.classId]){chosen=state.classId;}pending=false;render();q('.roster-note').textContent='Change class at any sanctuary. Your equipment and progress travel with you.';dialog.showModal();q('[data-class-choice="'+chosen+'"]').focus();try{await prepareCharacterPortraits();prepared=true;render();}catch(error){console.error('Character preview failed',error);prepared=true;render();q('.roster-note').textContent='Character portraits are unavailable. You can still choose a class and enter the game.';}},resolve(result){if(!pending)return;pending=false;if(result.ok){try{localStorage.setItem('hallowmere.character-choice',JSON.stringify({classId:chosen,appearanceId:CLASSES[chosen].concept}));}catch{}dialog.close();}else{render();q('.roster-note').textContent=result.reason||'Could not select that class.';}}};
}
